<template><Head><title>{{ run ? 'Изменение выпуска' : 'Новый выпуск' }}</title></Head><div class="mi-page"><div class="content-header"><div class="container-fluid"><h5 class="m-0">{{ run ? 'Изменение выпуска' : 'Новый выпуск' }}</h5></div></div><div class="content"><div class="container-fluid"><div class="card card-primary"><form @submit.prevent="submit"><div class="card-body"><div class="mx-auto col-md-6"><div class="form-group"><label>Продукция</label><select v-model.number="form.nomenclature_id" class="form-control"><option :value="null">Выберите продукцию</option><option v-for="product in products" :value="product.id">{{ product.name }}</option></select></div><div class="form-group"><label>Количество</label><input v-model="form.quantity" type="number" step="0.000001" min="0" class="form-control"></div><div class="form-group"><label>Дата выпуска</label><input v-model="form.produced_at" type="datetime-local" class="form-control"></div><div class="form-group"><label>Комментарий</label><textarea v-model="form.comment" class="form-control"></textarea></div></div></div><div class="card-footer mi-actions"><button class="btn btn-primary" :disabled="form.processing">Сохранить</button><Link :href="route('production-runs.index')" class="btn btn-default">Отмена</Link></div></form></div></div></div></div></template>
<script>import {Head, Link, useForm} from '@inertiajs/inertia-vue3'; export default {components: {Head, Link}, props: ['run', 'products', 'errors'], data() { return {form: useForm({nomenclature_id: this.run?.nomenclature_id || null, quantity: this.run?.quantity || null, produced_at: this.run?.produced_at || new Date().toISOString().slice(0, 16), comment: this.run?.comment || ''})} }, methods: {submit() { this.run ? this.form.put(route('production-runs.update', this.run.id)) : this.form.post(route('production-runs.store')) }}};</script>
